<?php
/**
 * Pro extension catalog reader.
 *
 * Reads the bundled `data/pro-features.json` snapshot of Pro extension
 * manifests so the Pro Features admin page can render on Free-only installs
 * without the Pro plugin being on disk.
 *
 * The snapshot is regenerated by `bin/sync-pro-catalog.php` before each Free
 * release. See plan: docs/plans/08-pro-promotion.md.
 *
 * @package Learnomy\Admin
 */

namespace Learnomy\Admin;

defined( 'ABSPATH' ) || exit;

final class Pro_Catalog {

	/**
	 * In-memory cache so multiple page-render reads don't re-parse JSON.
	 *
	 * @var array<int, array<string, mixed>>|null
	 */
	private static ?array $cache = null;

	/**
	 * Display order for the category groups on the Pro Features page.
	 *
	 * Slugs in the JSON snapshot use lower-case category strings. The view
	 * iterates this list and shows each group; categories not in the list
	 * fall through to the catch-all `operations` bucket.
	 *
	 * @return array<string, string>
	 */
	public static function category_labels(): array {
		return array(
			'core'              => __( 'Core', 'learnomy' ),
			'content'           => __( 'Content', 'learnomy' ),
			'student'           => __( 'Student experience', 'learnomy' ),
			'commerce'          => __( 'Commerce', 'learnomy' ),
			'community'         => __( 'Community', 'learnomy' ),
			'integrations'      => __( 'Integrations', 'learnomy' ),
			// Content standards + interop (SCORM, xAPI, LTI, QTI, H5P). Their own
			// group because they are a coherent enterprise buying decision, not
			// assorted 'operations'.
			'standards'         => __( 'Standards & interop', 'learnomy' ),
			'reporting'         => __( 'Reporting', 'learnomy' ),
			'operations'        => __( 'Operations', 'learnomy' ),
			'course-management' => __( 'Course management', 'learnomy' ),
		);
	}

	/**
	 * Get all Free modules in the same shape as Pro features so the view
	 * can iterate one mixed list. Source is the base Free catalog (not the
	 * filtered `learnomy_modules_catalog` output) so Pro rows don't sneak
	 * in as Free.
	 *
	 * @return array<int, array<string, mixed>>
	 */
	public static function free_modules(): array {
		if ( ! class_exists( '\\Learnomy\\Modules\\Module_Kernel' ) ) {
			return array();
		}

		// Read the base Free catalog directly via reflection of the static
		// method. We call catalog() then strip any `is_pro` rows so Pro
		// extensions contributed by the filter don't pollute the Free list.
		$catalog = \Learnomy\Modules\Module_Kernel::catalog();
		$free    = array();

		foreach ( $catalog as $slug => $row ) {
			if ( ! empty( $row['is_pro'] ) ) {
				continue;
			}
			$free[] = array(
				'slug'         => (string) $slug,
				'name'         => (string) ( $row['name'] ?? $slug ),
				'description'  => (string) ( $row['description'] ?? '' ),
				'category'     => (string) ( $row['category'] ?? 'operations' ),
				'tier'         => 'free',
				'required'     => ! empty( $row['required'] ),
				'default'      => ! empty( $row['default'] ),
				'status'       => 'stable',
				'user_stories' => array(),
			);
		}

		usort(
			$free,
			static fn( array $a, array $b ): int => strcasecmp( (string) $a['name'], (string) $b['name'] )
		);

		return $free;
	}

	/**
	 * Free + Pro merged into one alphabetically-sorted list with a `tier`
	 * field on every row. The view renders this in a single grid and uses
	 * the tier value to colour the FREE / PRO pill on each card.
	 *
	 * @return array<int, array<string, mixed>>
	 */
	public static function unified_catalog(): array {
		$free = self::free_modules();

		$pro = array();
		foreach ( self::get_all() as $row ) {
			$row['tier'] = 'pro';
			$pro[]       = $row;
		}

		$merged = array_merge( $free, $pro );

		usort(
			$merged,
			static fn( array $a, array $b ): int => strcasecmp( (string) $a['name'], (string) $b['name'] )
		);

		return $merged;
	}

	/**
	 * Get all Pro features, in stable display order (category bucket → name).
	 *
	 * @return array<int, array<string, mixed>>
	 */
	public static function get_all(): array {
		if ( null !== self::$cache ) {
			return self::$cache;
		}

		$path = LEARNOMY_DIR . 'data/pro-features.json';

		if ( ! is_readable( $path ) ) {
			self::$cache = array();
			return self::$cache;
		}

		// Local bundled file — file_get_contents is the WordPress-recommended
		// approach for filesystem reads; the sniff is for remote URLs.
		$raw = file_get_contents( $path ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_get_contents_file_get_contents
		if ( false === $raw ) {
			self::$cache = array();
			return self::$cache;
		}

		$decoded = json_decode( $raw, true );
		if ( ! is_array( $decoded ) || empty( $decoded['features'] ) || ! is_array( $decoded['features'] ) ) {
			self::$cache = array();
			return self::$cache;
		}

		self::$cache = array_values( array_map( array( self::class, 'normalise' ), $decoded['features'] ) );
		return self::$cache;
	}

	/**
	 * Group features by category in the display order from `category_labels()`.
	 *
	 * Unknown categories fall into the `operations` bucket so the page never
	 * silently drops a feature when a future Pro extension adds a new
	 * category that the Free snapshot doesn't yet know about.
	 *
	 * @return array<string, array<int, array<string, mixed>>>
	 */
	public static function grouped_by_category(): array {
		$labels  = self::category_labels();
		$grouped = array_fill_keys( array_keys( $labels ), array() );

		foreach ( self::get_all() as $feature ) {
			$cat = $feature['category'] ?? 'operations';

			// An unrecognised category used to fall through here silently, which
			// is how six features (h5p, lti, qti, scorm, xapi, wp-fusion) sat in
			// "Operations" for months: data/pro-features.json spelled the slug
			// `integration` while the label map defines `integrations`, and a
			// one-character mismatch is invisible when the fallback says nothing.
			// It still degrades gracefully — a mis-slugged feature must never
			// vanish from the page — but it now says so out loud in debug builds
			// so the next typo surfaces in review instead of after a customer
			// asks where SCORM went.
			if ( ! isset( $grouped[ $cat ] ) ) {
				if ( defined( 'WP_DEBUG' ) && WP_DEBUG ) {
					_doing_it_wrong(
						__METHOD__,
						sprintf(
							/* translators: 1: category slug, 2: feature slug */
							esc_html__( 'Unknown Pro feature category "%1$s" on "%2$s". Falling back to Operations. Add it to category_labels() or fix the slug in data/pro-features.json.', 'learnomy' ),
							esc_html( (string) $cat ),
							esc_html( (string) ( $feature['slug'] ?? '?' ) )
						),
						'1.7.1'
					);
				}
				$cat = 'operations';
			}

			$grouped[ $cat ][] = $feature;
		}

		// Sort each bucket alphabetically by name for stable rendering.
		foreach ( $grouped as &$bucket ) {
			usort( $bucket, static fn( array $a, array $b ): int => strcasecmp( (string) $a['name'], (string) $b['name'] ) );
		}
		unset( $bucket );

		return $grouped;
	}

	/**
	 * Look up a single feature by slug.
	 *
	 * Used by the empty-state partial so list pages can pull a Pro feature
	 * card by slug ("memberships-pro") without the caller needing to know
	 * the catalog shape.
	 */
	public static function find( string $slug ): ?array {
		foreach ( self::get_all() as $feature ) {
			if ( ( $feature['slug'] ?? '' ) === $slug ) {
				return $feature;
			}
		}
		return null;
	}

	/**
	 * Slugs of Pro extensions currently *active* on this site.
	 *
	 * Read from the live `learnomy_modules_catalog` filter — when Pro is
	 * installed, its kernel adds `is_pro: true` rows that the filter exposes.
	 * The Pro Features page uses this set to flip a card from "Coming with
	 * Pro" to "Active on this site".
	 *
	 * @return array<int, string>
	 */
	public static function active_slugs_on_site(): array {
		if ( ! class_exists( '\\Learnomy\\Modules\\Module_Kernel' ) ) {
			return array();
		}

		$catalog     = \Learnomy\Modules\Module_Kernel::catalog();
		$pro_enabled = (array) get_option( 'learnomy_pro_extensions', array() );

		$active = array();
		foreach ( $catalog as $row ) {
			if ( empty( $row['is_pro'] ) || empty( $row['pro_id'] ) ) {
				continue;
			}
			if ( in_array( $row['pro_id'], $pro_enabled, true ) ) {
				$active[] = (string) $row['pro_id'];
			}
		}
		return $active;
	}

	/**
	 * Whether the Pro plugin is loaded on this site.
	 *
	 * The Modules-page notice and contextual upsells only render when this
	 * returns false, so the operator never sees "consider Pro" copy on a
	 * site that already has Pro installed.
	 */
	public static function pro_plugin_active(): bool {
		return defined( 'LEARNOMY_PRO_VERSION' ) || class_exists( '\\Learnomy_Pro\\Plugin' );
	}

	/**
	 * Normalise a snapshot row to the shape the view expects.
	 *
	 * @param array<string, mixed> $row
	 * @return array<string, mixed>
	 */
	private static function normalise( array $row ): array {
		$name        = (string) ( $row['name'] ?? ( $row['slug'] ?? '' ) );
		$description = (string) ( $row['description'] ?? '' );
		$stories     = array_values( array_map( 'strval', (array) ( $row['user_stories'] ?? array() ) ) );

		return array(
			'slug'         => (string) ( $row['slug'] ?? '' ),
			'name'         => self::translate_catalog_string( $name ),
			'description'  => self::translate_catalog_string( $description ),
			'category'     => (string) ( $row['category'] ?? 'operations' ),
			'status'       => (string) ( $row['status'] ?? 'beta' ),
			'version'      => (string) ( $row['version'] ?? '1.0.0' ),
			'user_stories' => array_map( array( self::class, 'translate_catalog_string' ), $stories ),
		);
	}

	/**
	 * Translate a catalog string sourced from data/pro-features.json.
	 *
	 * The JSON values are POT-invisible, so every one of them has a matching
	 * __() msgid home in data/pro-features-i18n.php. At runtime we gettext the
	 * English value against the text domain; if no translation exists the
	 * English is returned unchanged (the JSON acts as the source-of-truth
	 * fallback).
	 *
	 * @param string $text English catalog string.
	 */
	private static function translate_catalog_string( string $text ): string {
		if ( '' === $text ) {
			return $text;
		}
		// $text is a registered msgid (see data/pro-features-i18n.php); translate()
		// is the correct API for gettext-translating a dynamically-sourced string.
		return translate( $text, 'learnomy' ); // phpcs:ignore WordPress.WP.I18n.NonSingularStringLiteralText
	}
}
